import React from 'react';

import { useNavigate } from 'react-router-dom';
import { Link } from 'react-router-dom';
import { NavLink } from 'react-router-dom';

import { getEquipStats } from '@apps/Hiking/@services/equip.service';
import { IEquipWithUsagesStat } from '@apps/Hiking/@types/equip.types';
import { editEquipModal } from '@apps/Hiking/equip/HikingEquip/addEquip/editEquipModal';
import { previewEquipModal } from '@apps/Hiking/equip/HikingEquip/previewEquip/previewEduipModal';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { declOfNum } from '@helpers/formatHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import EquipList from '../components/EquipList';
import EquipListItem from '../components/EquipListItem';
import EquipSetListItem from '../components/EquipSetListItem';

const EquipPage: React.FC<{ id_equip: number }> = ({ id_equip }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IEquipWithUsagesStat>();

  const navigate = useNavigate();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getEquipStats(id_equip);
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_equip]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!data) return <PohAlert variant={AlertVariant.Danger}>has no data</PohAlert>;

  return (
    <div>
      <PohBreadcrumbs
        data={[
          { href: '/equip', text: 'Снаряжение' },
          { href: '/equip/' + data.id, text: data.name, active: true },
        ]}
      />

      <PohContainer>
        <PageHeader title={data.name}>
          <PohButton
            size={ButtonSize.Small}
            onClick={() =>
              editEquipModal(data, (up) => {
                setData((cur) => ({ ...cur, ...(up as IEquipWithUsagesStat) }));
              })
            }
            className="me-2"
          >
            Редактировать
          </PohButton>
        </PageHeader>
        <PohRow className="mt-n2 mb-2">
          <PohCol sm={2}>
            <img src={data.photo} alt={data.name} className="w-100" />
          </PohCol>
          <PohCol sm={3}>
            <p className="my-1 mt-4">
              <div>
                {data.category?.name ? (
                  <NavLink to={`/equip?id_category=${data.category.id}`}>
                    {data.category.name}
                  </NavLink>
                ) : (
                  'Без категории'
                )}
              </div>
              <small className="d-block mt-n1 text-muted">Категория</small>
            </p>
            <p className="my-1">
              <div>{data.weight}&thinsp;г.</div>
              <small className="d-block mt-n1 text-muted">Вес</small>
            </p>

            <p className="my-1">
              <div>{data.value}&thinsp;л.</div>
              <small className="d-block mt-n1 text-muted">Объем</small>
            </p>
            <p className="my-1">
              {data.is_archive && <PohBadge variant={BadgeVariant.Warning}>Архивное</PohBadge>}

              {data.is_group && <PohBadge variant={BadgeVariant.Success}>Групповое</PohBadge>}

              {data.is_musthave && <PohBadge variant={BadgeVariant.Primary}>Обязательное</PohBadge>}
            </p>
          </PohCol>
          <PohCol sm={2}>
            <p className="my-1 mt-4">
              <div>
                {data.usages.length}&thinsp;{declOfNum(data.usages.length, ['раз', 'раза', 'раз'])}
              </div>
              <small className="d-block mt-n1 text-muted">Использовалось</small>
            </p>
            <p className="my-1">
              <div>{data.usages?.[0]?.date_update?.toLocaleDateString() ?? '-'}</div>
              <small className="d-block mt-n1 text-muted">Первый раз</small>
            </p>

            <p className="my-1">
              <div>
                {data.usages?.[data.usages.length - 1]?.date_update?.toLocaleDateString() ?? '-'}
              </div>
              <small className="d-block mt-n1 text-muted">
                {data.is_archive ? 'Последний' : 'Крайний'} раз
              </small>
            </p>
            <p className="my-1"></p>
          </PohCol>

          <PohCol sm={2}>
            {data.parent && (
              <p className="my-1 mt-4">
                <div>
                  <Link to={`/equip/${data.parent.id}`}>
                    <EquipListItem item={data.parent} />
                  </Link>
                </div>
                <small className="d-block mt-n1 text-muted">
                  Является частью другого снаряжения
                </small>
              </p>
            )}
          </PohCol>
          <PohCol sm={3}>
            <EquipList
              criteria={{ id_parent: data.id }}
              header={<h6>Дочерние элементы</h6>}
              onSelectEquipItem={(item, e) => {
                e.ctrlKey || e.altKey ? previewEquipModal(item) : navigate(`/equip/${item.id}`);
              }}
            />
          </PohCol>
        </PohRow>
        {data.usages.length === 0 && <Empty>Похоже вы не добавляли этот элемент в сборку</Empty>}
        {data.usages.length > 0 && (
          <section>
            <h5>Есть в сборках</h5>
            <PohList
              data={data.usages.map((item) => {
                return {
                  key: item.id,
                  children: <EquipSetListItem item={item} />,
                  onClick: () => navigate(`/equip/sets/${item.id}`),
                };
              })}
            />
          </section>
        )}
      </PohContainer>
    </div>
  );
};

export default EquipPage;
